import{e as t,ab as a,a1 as i,m as o,r as s,p as n}from"./chunks/framework.BGh0NSIy.js";const g=JSON.parse('{"title":"Monthly Updates [Feb]","description":"February 2025 updates.","frontmatter":{"title":"Monthly Updates [Feb]","description":"February 2025 updates.","date":"2025-02-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/feb-2025.md","filePath":"posts/feb-2025.md"}'),l={name:"posts/feb-2025.md"};function d(p,e,h,f,m,c){const r=a("Post");return i(),o("div",null,[s(r,{authors:"nbats"}),e[0]||(e[0]=n('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Added <a href="https://fmhy.net/audio#concerts-live-shows" target="_blank" rel="noreferrer">Concerts / Live Shows</a> section to Audio.</p></li><li><p>Added <a href="https://fmhy.net/audio#genre-specific" target="_blank" rel="noreferrer">Genre Specific</a> section to Audio Downloading.</p></li><li><p>Added <a href="https://fmhy.net/misc#drinks" target="_blank" rel="noreferrer">Drinks</a> section under Food.</p></li><li><p>Moved <a href="https://fmhy.net/misc#collaboration-platforms" target="_blank" rel="noreferrer">Collaboration Platforms</a> out of storage, cleaned up the section, and added labels.</p></li><li><p>For individual notes, we&#39;ve stopped linking to pastebins and instead link to our own <a href="https://github.com/fmhy/FMHY/wiki/FMHY%E2%80%90Notes.md" target="_blank" rel="noreferrer">GitHub page</a>.</p></li><li><p>Added a <a href="https://github.com/fmhy/FMHY/wiki/Stream-Site-Grading" target="_blank" rel="noreferrer">Site Grading System</a> for streaming to help sort them more fairly. This is currently a work in progress, and more categories will be added to further separate sites at the top, such as mobile optimization, ad-free streaming, watch list syncing, and more.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/ai#online-chatbots" target="_blank" rel="noreferrer">DeepSeek</a> in Online Chatbots. V3 is unlimited, and people seem to be really liking it so far.</p></li><li><p>Starred <a href="https://fmhy.net/video#anime-streaming" target="_blank" rel="noreferrer">AnimeZ</a> in Anime Streaming. Has fast streams and did well in our polls.</p></li><li><p>Starred <a href="https://fmhy.net/video#download-sites" target="_blank" rel="noreferrer">OOMoye</a> + <a href="https://fmhy.net/video#drives-directories" target="_blank" rel="noreferrer">PKMovies</a> under Video Download. Both have big libraries, fast hosts, and single-click downloads.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#game-saves" target="_blank" rel="noreferrer">Ludusavi</a> in Game Saves. Feature-rich game save manager that supports all platforms.</p></li><li><p>Starred <a href="https://fmhy.net/video#live-tv" target="_blank" rel="noreferrer">TV Garden</a> in Live TV. Nice UI, lots of channels, and consistent compared to similar options.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-youtube-apps" target="_blank" rel="noreferrer">PipePipe</a> in Android YouTube Apps. Feature-rich fork of NewPipe w/ SponsorBlock / ReturnYTDislikes.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#pokemon-tools" target="_blank" rel="noreferrer">PokéRogue</a> in Pokémon section. Popular and fun Pokémon dungeon crawler.</p></li><li><p>Starred <a href="https://fmhy.net/video-tools#stream-sync" target="_blank" rel="noreferrer">WatchParty</a> in Stream Sync. Feature-rich video sync app that seems to work well for people.</p></li><li><p>Starred <a href="https://fmhy.net/image-tools#gif-tools" target="_blank" rel="noreferrer">Gifski + EZGif</a> under GIF Tools. High-quality GIF creation tools.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#telegram-channels-1" target="_blank" rel="noreferrer">Blatant&#39;s IPA Library</a> in iOS Apps. High-quality iOS app releases; stands out compared to similar TG groups.</p></li><li><p>Starred <a href="https://fmhy.net/audio#audio-editors" target="_blank" rel="noreferrer">Reaper</a> under Audio Editors. Feature-rich digital audio workstation. It says it&#39;s a trial, but the trial never actually ends.</p></li><li><p>Added star back to <a href="https://fmhy.net/gaming#download-games" target="_blank" rel="noreferrer">SteamGG</a> in Game DDL. Game download site with pre-installs and good hosts, similar to SteamRIP.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Unstarred Firehawk52 as Deezer ARLs are being nuked instantly now.</p></li><li><p>Unstarred IPALibrary and replaced it with <a href="https://fmhy.net/mobile#ios-ipas" target="_blank" rel="noreferrer">CodeVN</a>, as this is where IPALibrary sources its apps.</p></li></ul>',9))])}const b=t(l,[["render",d]]);export{g as __pageData,b as default};
